            border: 1px solid var(--border-color);
            border-radius: 4px;
            background-color: #fff;
            margin-top: 0.5rem;
            display: none;
        }
        .grid-item.selected .custom-input { display: block; }

        /* Pocket Watch Effect */
        .pocket-watch-effect {
            position: absolute;
            width: 80px;
            height: 80px;
            background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100" width="100" height="100"><g fill="none" stroke="%235d4037" stroke-width="2"><circle cx="50" cy="50" r="48"/><path d="M50 2v-2M50 98v2M2 50h-2M98 50h2"/><circle cx="50" cy="50" r="4"/><path d="M50 50 L50 20 M50 50 L75 50"/></g><g stroke="%235d4037" stroke-width="1"><path d="M50 10 L50 12 M50 90 L50 88 M10 50 L12 50 M90 50 L88 50 M22 22 L24 24 M78 78 L76 76 M22 78 L24 76 M78 22 L76 24"/></g></svg>');
            background-size: contain;
            background-repeat: no-repeat;
            transform: translate(-50%, -50%) scale(0);
            opacity: 0;
            animation: watch-burst 0.6s cubic-bezier(0.1, 0.8, 0.7, 1) forwards;
            pointer-events: none;
            z-index: 9999;
        }

        @keyframes watch-burst {
            0% { transform: translate(-50%, -50%) scale(0.5); opacity: 1; }
            60% { transform: translate(-50%, -50%) scale(1.2); opacity: 0.8; }
            100% { transform: translate(-50%, -50%) scale(1.5); opacity: 0; }
        }

        /* Start Game Button */
        #start-game-btn {
            width: 80%;
            max-width: 400px;
            padding: 1.2rem;
            font-size: 1.6rem;
