        #result-container.visible { opacity: 1; transform: translateY(0); }
        #result-text {
            padding: 2rem;
            background: url('data:image/svg+xml;utf8,<svg width="100" height="100" opacity="0.05" xmlns="http://www.w3.org/2000/svg"><path d="M25 50 C45 20, 55 20, 75 50 S105 80, 125 50" stroke="black" fill="transparent"/></svg>'), var(--bg-color);
            border: 2px solid var(--text-color);
            border-radius: 15px;
            white-space: pre-wrap;
            line-height: 2;
            font-size: 1.2rem;
            box-shadow: 0 5px 15px var(--shadow-color);
            text-align: left;
        }

        #other-requirements-input::placeholder {
            color: var(--text-color);
            opacity: 0.6;
        }

    </style>
</head>
<body>

    <div class="main-panel">
        <h1>创建你的故事</h1>

        <!-- Basic Info -->
        <h2>基础信息</h2>
        <div class="info-grid">
            <div class="info-item">
                <label>性别</label>
                <div class="option-select">
                    <div class="option-btn gender-option selected" data-gender="男">男</div>
                    <div class="option-btn gender-option" data-gender="女">女</div>
                    <div class="option-btn gender-option" data-gender="自定义">自定义</div>
                </div>
                <input type="text" id="custom-gender-input" class="styled-input" placeholder="输入自定义性别" style="display: none; margin-top: 0.75rem;">
            </div>
            <div class="info-item">
                <label for="age-input">年龄</label>
                <input type="number" id="age-input" class="styled-input" placeholder="例如：18">
            </div>
            <div class="info-item">
                <label for="race-input">种族</label>
                <input type="text" id="race-input" class="styled-input" placeholder="例如：人类">
            </div>
        </div>

        <!-- Alignment and Identity -->
        <h2>阵营与身份</h2>
        <div class="info-item" style="margin-bottom: 1.5rem;">
            <label>属性</label>
            <div class="option-select">
                <div class="option-btn alignment-option selected" data-alignment="善良守序">善良守序</div>
                <div class="option-btn alignment-option" data-alignment="堕落自由">堕落自由</div>
            </div>
        </div>
        <div class="info-item">
            <label>身份 (单选)</label>
            <div id="identity-selection" class="selection-grid"></div>
        </div>

        <!-- Location -->
        <div class="location-section">
            <span style="font-size: 1.2rem;">你的故事始于 </span>
            <span id="location-display"></span>
            <button id="random-location-btn" class="random-btn">命运的指引</button>
        </div>

        <!-- Active Skills -->
        <h2>主动技能 (至多选三个)</h2>
        <div id="active-skills" class="selection-grid"></div>

        <!-- Passive Skills -->
        <h2>被动技能 (至多选3个)</h2>
        <div id="passive-skills" class="selection-grid"></div>

        <!-- 其他要求 -->
        <h2>其他要求</h2>
        <div class="info-item">
            <textarea id="other-requirements-input" class="styled-input" rows="4" placeholder="详细的外貌、背景、性格、能力等，可留空。例如：银发赤瞳，性格沉稳..."></textarea>
        </div>

        <!-- Start Game -->
