    <script>
    document.addEventListener('DOMContentLoaded', () => {
        const locations = ["尼尼微", "所多玛", "乌斯地", "归乡角", "荒野", "蛾摩拉号"];
        const identities = ["贵族", "骑士", "游侠", "恶徒", "学者", "修士", "农民", "市民", "商人", "佣兵"];
        const activeSkillsList = ["魔物作成", "超电磁炮", "爆裂魔法", "无限剑制", "倾国倾城", "回归枢机之光（Sparagmos）", "水之呼吸", "镜花水月", "万象天引", "不可视之手", "大贤者", "模拟创星图·真相不明（Code Unknown）"];
        const passiveSkillsList = ["死亡回归", "一心憧憬", "零时迷子", "幻想杀手", "生命目录（Genome Tree）", "十二试炼", "射杀百头", "未来日记", "直死之魔眼", "来自深渊", "邪王真眼", "帝王引擎"];

        const locationDisplay = document.getElementById('location-display');
        const randomLocationBtn = document.getElementById('random-location-btn');
        const identityContainer = document.getElementById('identity-selection');
        const activeSkillsContainer = document.getElementById('active-skills');
        const passiveSkillsContainer = document.getElementById('passive-skills');
        const startGameBtn = document.getElementById('start-game-btn');
        const resultContainer = document.getElementById('result-container');
        const resultText = document.getElementById('result-text');

        // --- Pocket Watch Effect ---
        function createPocketWatchEffect(event) {
            const effect = document.createElement('div');
            effect.className = 'pocket-watch-effect';
            effect.style.left = `${event.pageX}px`;
            effect.style.top = `${event.pageY}px`;
            document.body.appendChild(effect);
            setTimeout(() => {
                effect.remove();
            }, 600);
        }

        // --- Generic Option Selector ---
        function setupOptionSelector(selector, customInputId) {
            const options = document.querySelectorAll(selector);
            const customInput = customInputId ? document.getElementById(customInputId) : null;
            options.forEach(option => {
                option.addEventListener('click', (e) => {
                    createPocketWatchEffect(e);
                    options.forEach(opt => opt.classList.remove('selected'));
                    option.classList.add('selected');
                    if (customInput) {
                        customInput.style.display = option.dataset.gender === '自定义' ? 'block' : 'none';
                        if (option.dataset.gender === '自定义') customInput.focus();
                    }
                });
            });
        }
        setupOptionSelector('.gender-option', 'custom-gender-input');
        setupOptionSelector('.alignment-option');

        // --- Location ---
        function randomizeLocation(event) {
            if(event) createPocketWatchEffect(event);
            const randomIndex = Math.floor(Math.random() * locations.length);
            locationDisplay.textContent = locations[randomIndex];
            locationDisplay.style.transform = 'scale(0.8)';
            setTimeout(() => { locationDisplay.style.transform = 'scale(1)'; }, 100);
        }
        randomLocationBtn.addEventListener('click', randomizeLocation);
        randomizeLocation();

        // --- Populate Grids ---
        function populateGrid(container, items, type, selectionLimit) {
            items.forEach(item => {
                const el = document.createElement('div');
                el.className = 'grid-item';
                el.textContent = item;
                el.dataset.type = type;
                el.dataset.value = item;
                container.appendChild(el);
            });
            const customItem = document.createElement('div');
            customItem.className = 'grid-item';
            customItem.dataset.type = type;
            customItem.dataset.value = 'custom';
            customItem.innerHTML = `自定义... <input type="text" class="custom-input" placeholder="输入${type === 'identity' ? '身份' : '技能'}名">`;
            container.appendChild(customItem);

            // Selection Logic
            container.querySelectorAll('.grid-item').forEach(item => {
                item.addEventListener('click', (e) => {
                    if (e.target.tagName === 'INPUT') return;

                    const isSelected = item.classList.contains('selected');
                    const selectedCount = container.querySelectorAll('.grid-item.selected').length;

                    if (selectionLimit === 1) {
                        container.querySelectorAll('.grid-item').forEach(i => i.classList.remove('selected'));
                        if (!isSelected) item.classList.add('selected');
                    } else {
                        if (!isSelected && selectedCount >= selectionLimit) {
                            alert(`最多只能选择${selectionLimit}个${type === 'active' ? '主动技能' : '被动技能'}！`);
                            return;
                        }
                        item.classList.toggle('selected');
                    }

                    if (item.classList.contains('selected')) createPocketWatchEffect(e);

                    container.querySelectorAll('.custom-input').forEach(input => input.style.display = 'none');
                    const customInput = item.querySelector('.custom-input');
                    if (customInput && item.classList.contains('selected')) {
                        customInput.style.display = 'block';
                        customInput.focus();
                    }
                });
            });
        }
        populateGrid(identityContainer, identities, 'identity', 1);
        populateGrid(activeSkillsContainer, activeSkillsList, 'active', 3);
        populateGrid(passiveSkillsContainer, passiveSkillsList, 'passive', 3);

        // --- Start Game ---
        startGameBtn.addEventListener('click', async () => {
            // Get Basic Info
            const selectedGenderEl = document.querySelector('.gender-option.selected');
            let gender = selectedGenderEl ? selectedGenderEl.dataset.gender : '未设定';
            if (gender === '自定义') {
                gender = document.getElementById('custom-gender-input').value.trim() || '自定义';
            }
            const age = document.getElementById('age-input').value.trim() || '未知';
            const race = document.getElementById('race-input').value.trim() || '未知';
            const otherRequirements = document.getElementById('other-requirements-input').value.trim() || '无';

            // Get Alignment & Identity
            const selectedAlignmentEl = document.querySelector('.alignment-option.selected');
            const alignment = selectedAlignmentEl ? selectedAlignmentEl.dataset.alignment : '未定';

            function getSelectedGridItem(containerId) {
                const container = document.getElementById(containerId);
                const selectedEl = container.querySelector('.grid-item.selected');
                if (!selectedEl) return '未定';
                if (selectedEl.dataset.value === 'custom') {
                    const input = selectedEl.querySelector('.custom-input');
                    return (input && input.value.trim()) ? input.value.trim() : '自定义';
                }
                return selectedEl.dataset.value;
            }
            const identity = getSelectedGridItem('identity-selection');

            // Get Location
            const selectedLocation = locationDisplay.textContent;

            // Get Skills
            function getSelectedSkillsAsArray(containerId) {
                const selected = [];
                const items = document.querySelectorAll(`#${containerId} .grid-item.selected`);
                items.forEach(item => {
                    if (item.dataset.value === 'custom') {
                        const customInput = item.querySelector('.custom-input');
                        if (customInput && customInput.value.trim()) {
                            selected.push(customInput.value.trim());
                        }
                    } else {
                        selected.push(item.dataset.value);
                    }
                });
                return selected;
            }
            const activeSkillsArray = getSelectedSkillsAsArray('active-skills');
            const passiveSkillsArray = getSelectedSkillsAsArray('passive-skills');
            const finalActiveSkills = activeSkillsArray.length > 0 ? activeSkillsArray.join('、') : '无';
            const finalPassiveSkills = passiveSkillsArray.length > 0 ? passiveSkillsArray.join('、') : '无';

            // Create Story
            const story = `一位【${alignment}】的【${age}】岁【${race}】【${gender}】【${identity}】，就此踏上旅途。\n\n命运赋予了你初始的权柄：\n❖ 天予权能：${finalActiveSkills}\n❖ 命定之理：${finalPassiveSkills}\n\n你的史诗，将在【${selectedLocation}】揭开序幕……`;

            resultText.textContent = story;
            resultContainer.classList.add('visible');

            // --- SillyTavern Integration ---
            const characterData = {
                'characters.<user>.race': race,
                'characters.<user>.gender': gender,
                'characters.<user>.age': isNaN(parseInt(age)) ? null : parseInt(age),
                'characters.<user>.alignment': alignment,
                'characters.<user>.identity': identity,
                'characters.<user>.skills.active': activeSkillsArray,
                'characters.<user>.skills.passive': passiveSkillsArray,
                'characters.<user>.other_requirements': otherRequirements === '无' ? '' : otherRequirements,
                'location': selectedLocation
            };

            const slashCommand = `/send return=pipe 故事开始的地点为：${selectedLocation}\n` +
                                 `<user>的主动技能为：${finalActiveSkills}\n` +
                                 `<user>的被动技能为：${finalPassiveSkills}\n` +
                                 `种族为：${race}，性别为：${gender}，年龄为：${age}\n` +
                                 `身份：${identity}，阵营：${alignment}\n`+
                                 `其他要求：${otherRequirements}\n` +
                                 `请根据地点、身份、阵营、种族、年龄，为故事设置符合世界观的序章，主要描述<user>的过往经历、生活。\n` +
                                 `<p hidden>\n` +
                                 `_.set('characters.<user>.race', '', '${race}');\n` +
                                 `_.set('characters.<user>.gender', '', '${gender}');\n` +
                                 `_.set('characters.<user>.age', null, ${isNaN(parseInt(age)) ? 'null' : parseInt(age)});\n` +
                                 `_.set('characters.<user>.skills.active', [], ${JSON.stringify(activeSkillsArray)});\n` +
                                 `_.set('characters.<user>.skills.passive', [], ${JSON.stringify(passiveSkillsArray)});\n` +
                                 `_.set('location', '', '${selectedLocation}');`;

            const MessageContinue = `/trigger`;

            try {
                // Check for SillyTavern's specific functions
                if (typeof insertOrAssignVariables === 'function' && typeof triggerSlash === 'function') {
                    // Use the dedicated function to update variables
                    await insertOrAssignVariables(characterData);
                    console.log('Variables sent to SillyTavern via insertOrAssignVariables.');

                    // Send the text message
                    await triggerSlash(slashCommand, 'Send');
                    await triggerSlash(MessageContinue, 'Send');
                    console.log('Story message sent to SillyTavern via triggerSlash.');

                } else {
                    // Fallback for environments without the functions
                    console.log("SillyTavern functions not found. Creating fallback command for clipboard.");

                    const combinedCommand = `${slashCommand.replace('/send ', '')}\n`;

                    if (navigator.clipboard) {
                        await navigator.clipboard.writeText(combinedCommand);
                        const originalText = startGameBtn.textContent;
                        startGameBtn.textContent = '指令已复制!';
                        setTimeout(() => { startGameBtn.textContent = originalText; }, 2000);
                    } else {
                        // Fallback for older browsers
                        const textArea = document.createElement("textarea");
                        textArea.value = combinedCommand;
                        document.body.appendChild(textArea);
                        textArea.select();
                        document.execCommand('copy');
                        document.body.removeChild(textArea);
                        const originalText = startGameBtn.textContent;
                        startGameBtn.textContent = '指令已复制!';
                        setTimeout(() => { startGameBtn.textContent = originalText; }, 2000);
                    }
                }
            } catch (error) {
                console.error('An error occurred during SillyTavern interaction:', error);
                alert('操作失败，请查看浏览器控制台获取更多信息。');
            }

            // Lock the UI
            document.body.querySelectorAll('button, input, .option-btn, .grid-item').forEach(el => {
                el.disabled = true;
                el.style.cursor = 'not-allowed';
                el.style.pointerEvents = 'none';
            });
            startGameBtn.style.opacity = '0.6';
            document.querySelectorAll('.grid-item:not(.selected)').forEach(item => {
                item.style.opacity = '0.5';
            });
        });
    });
    </script>

</body>
</html>
