<!doctype html>
<html lang="zh-CN">

<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width,initial-scale=1">
    <title>角色状态栏 - 重构版</title>
    <style>
        /* --- CSS样式 --- */
        :root {
            --panel-bg: #f6f2ee;
            --card-bg: #fdfaf6;
            --text-color: #6e665e;
            --text-muted: #a8a29a;
            --border-color: #e7e2dc;
            --sub-item-bg: #f9f6f2;
            --hp-color: #e54848;
            --mp-color: #4a80e5;
            --favor-color: #f39c12;
            --gold-light: #d4b780;
            --gold-dark: #a68340;
        }

        @keyframes shimmer {
            0% {
                transform: translateX(-100%);
            }

            100% {
                transform: translateX(100%);
            }
        }

        .status-panel-wrapper * {
            box-sizing: border-box;
        }

        .status-panel-wrapper {
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
            max-width: 850px;
            margin: auto;
        }

        #status-panel {
            border-radius: 18px;
            padding: 0;
            overflow: hidden;
            border: 2px solid transparent;
            background-image: linear-gradient(var(--panel-bg), var(--panel-bg)), linear-gradient(145deg, var(--gold-light), var(--gold-dark));
            background-origin: border-box;
            background-clip: padding-box, border-box;
            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.08);
        }

        /* --- 统一的折叠动画逻辑 --- */
        .panel-content-collapsible {
            display: grid;
            grid-template-rows: 0fr; /* 默认折叠 */
            transition: grid-template-rows 0.35s ease-in-out; /* 动态效果 */
            overflow: hidden;
        }
        .module.is-collapsible > .collapsible-content {
            display: none;
        }

        h2.collapsible.active + .panel-content-collapsible {
            grid-template-rows: 1fr; /* For main panel animation */
        }
        h3.collapsible.active + .collapsible-content {
            display: block; /* For static inner panels */
        }

        /* 动画需要一个内部包裹元素，以正确计算高度 */
        .panel-content-collapsible > .main-content-wrapper,
        .collapsible-content > .content-inner-padding {
            min-height: 0;
        }
        /* --- End of animation logic --- */

        .module {
            background-color: var(--card-bg);
            border-radius: 12px;
            padding: 20px 22px;
            box-shadow: 0 4px 15px rgba(0, 0, 0, 0.04);
        }

        .main-content-wrapper > .module {
            margin: 12px;
        }

        .module.is-collapsible {
            padding: 0;
            overflow: hidden;
        }

        .module.is-collapsible > h3.collapsible {
            padding: 20px 22px;
            margin: 0;
            border-bottom: 1px solid var(--border-color);
            transition: none;
            font-weight: 600;
            font-size: 1.1em;
        }

        .module.is-collapsible > h3.collapsible.active {
            border-bottom-color: var(--border-color);
        }

        .collapsible-content > .content-inner-padding {
            padding: 20px 22px 4px 22px;
        }

        .character-module .content-inner-padding {
            padding-bottom: 20px;
        }

        .char-header {
            display: flex;
            justify-content: space-between;
            align-items: flex-start;
            margin-bottom: 20px;
        }

        .char-name {
            font-size: 2em;
            font-weight: 700;
            color: #5c544d;
        }

        .char-meta {
            font-size: 1em;
            color: var(--text-muted);
            text-align: right;
            line-height: 1.6;
        }

        .progress-bar-container {
            display: flex;
            align-items: center;
            margin-bottom: 12px;
            gap: 12px;
        }

        .progress-label {
            font-weight: bold;
            width: 35px;
            flex-shrink: 0;
            font-size: 1.1em;
        }

        .progress-bar-wrapper {
            position: relative;
            flex-grow: 1;
            background-color: #f0f0f0;
            border-radius: 8px;
            height: 16px;
            overflow: hidden;
        }

        .progress-bar {
            height: 100%;
            border-radius: 8px;
            transition: width 0.5s ease-in-out;
            width: calc(var(--val, 0) / var(--max, 1) * 100%);
        }

        .progress-bar.hp {
            background-color: var(--hp-color);
            box-shadow: 0 0 10px 1px var(--hp-color);
        }

        .progress-bar.mp {
            background-color: var(--mp-color);
            box-shadow: 0 0 10px 1px var(--mp-color);
        }

        .progress-bar::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: linear-gradient(90deg, rgba(255, 255, 255, 0) 0%, rgba(255, 255, 255, 0.2) 50%, rgba(255, 255, 255, 0) 100%);
            animation: shimmer 2s infinite linear;
        }

        .progress-value {
            font-size: 1em;
            font-weight: 500;
            font-variant-numeric: tabular-nums;
            min-width: 80px;
            text-align: right;
            color: var(--text-muted);
        }

        .content-section {
            margin-top: 24px;
        }

        .section-title {
            margin: 0 0 12px 0;
            color: var(--text-color);
            border-bottom: 1px solid var(--border-color);
            padding-bottom: 8px;
            font-weight: 600;
            font-size: 1.1em;
        }

        .tag-container {
            display: flex;
            flex-wrap: wrap;
            gap: 8px;
            list-style: none;
            padding: 0;
            margin: 0;
        }

        .item-tag {
            background-color: var(--sub-item-bg);
            border: 1px solid var(--border-color);
            color: var(--text-color);
            padding: 6px 14px;
            border-radius: 16px;
            font-size: 0.9em;
            transition: all 0.2s ease;
        }

        .item-tag:hover {
            transform: translateY(-2px);
            background-color: #fff;
            box-shadow: 0 3px 8px rgba(0, 0, 0, 0.06);
        }

        .collapsible {
            cursor: pointer;
            user-select: none;
            position: relative;
            font-weight: 600;
            margin: 0;
            padding: 0;
        }

        .collapsible:after {
            content: '▼';
            float: right;
            font-size: 0.8em;
            color: var(--text-muted);
            transition: transform 0.3s ease;
        }

        .collapsible.active:after {
            transform: rotate(180deg);
        }

        #status-panel > h2.collapsible {
            padding: 14px 16px;
            margin: 0;
            font-size: 1.1em;
            font-weight: 500;
            color: var(--text-muted);
            border-bottom: 1px solid transparent;
            transition: border-color 0.4s ease;
        }

        #status-panel > h2.collapsible.active {
            border-bottom-color: var(--border-color);
        }

        #status-panel > h2.collapsible:after {
            line-height: 1.4;
        }

        .module > h3.collapsible {
            font-size: 1.1em;
            color: var(--text-color);
        }

        .entity-list {
            list-style: none;
            padding: 0;
            margin: 0;
        }

        .entity-card {
            background-color: var(--sub-item-bg);
            border: 1px solid var(--border-color);
            border-radius: 10px;
            margin-bottom: 10px;
            padding: 12px 16px;
            transition: all 0.3s ease;
            cursor: pointer;
        }

        .entity-card:hover {
            border-color: var(--mp-color);
            box-shadow: 0 4px 10px rgba(0, 0, 0, 0.08);
            transform: translateY(-3px);
        }

        .entity-summary {
            display: flex;
            justify-content: space-between;
            align-items: center;
            font-size: 1.1em;
        }

        .entity-name {
            font-weight: 600;
            color: #555;
        }

        .entity-race {
            font-size: 0.9em;
            color: var(--text-muted);
            margin-left: 8px;
        }

        .entity-status {
            font-weight: 500;
            padding: 4px 8px;
            border-radius: 6px;
            font-size: 0.9em;
            background-color: #edeae7;
            color: #7a736c;
        }

        .entity-details {
            display: none; /* 卡片详情默认隐藏 */
            margin-top: 12px;
            padding-top: 12px;
            border-top: 1px dashed var(--border-color);
        }

        .entity-card.expanded > .entity-details {
            display: block; /* 展开的卡片显示详情 */
        }

        .entity-card.expanded {
            background-color: #fff;
        }

        .detail-grid {
            display: grid;
            grid-template-columns: auto 1fr;
            gap: 8px 16px;
            font-size: 0.9em;
            margin-bottom: 12px;
            align-items: center;
        }

        .detail-grid .label {
            color: var(--text-muted);
            text-align: right;
        }

        .detail-grid .value {
            font-weight: 500;
        }

        .sub-skills-list {
            list-style: none;
            padding: 10px;
            margin-top: 8px;
            background-color: #f2f0ed;
            border-radius: 6px;
            display: flex;
            flex-wrap: wrap;
            gap: 6px;
        }

        .sub-skills-list li {
            background-color: #e9e5e1;
            color: #6e665e;
            padding: 4px 8px;
            border-radius: 4px;
            font-size: 0.85em;
        }

        .event-content, .action-status-text {
            color: var(--text-color);
            font-size: 0.95em;
            line-height: 1.6;
            margin: 0;
        }
    </style>
</head>

<body>
    <pre id="raw-json-data" style="display:none;">$1</pre>
    <div class="status-panel-wrapper">
        <div id="status-panel">
            <!-- 初始状态：主面板默认折叠 -->
            <h2 class="collapsible">状态总览</h2>
            <div class="panel-content-collapsible">
                <div class="main-content-wrapper">
                    <div class="module character-module is-collapsible">
                        <h3 class="collapsible active"><user>状态栏</h3>
                        <div class="collapsible-content">
                            <div class="content-inner-padding" id="character-module-content"></div>
                        </div>
                    </div>
                    <div class="module teammate-module is-collapsible">
                        <h3 class="collapsible">队友</h3>
                        <div class="collapsible-content teammate-info"></div>
                    </div>
                    <div class="module npc-module is-collapsible">
                        <h3 class="collapsible">NPC</h3>
                        <div class="collapsible-content npc-info"></div>
                    </div>
                    <div class="module time-location-module">
                        <h3 class="section-title">时空信息</h3>
                        <p class="action-status-text"><strong>时间:</strong> <span id="time-text"></span></p>
                        <p class="action-status-text" style="margin-top: 8px;"><strong>地点:</strong> <span id="location-text"></span></p>
                    </div>
                    <div class="module event-module">
                        <h3 class="section-title">当前事件</h3>
                        <p id="event-text" class="event-content"></p>
                    </div>
                </div>
            </div>
        </div>
    </div>

    <script>
        document.addEventListener('DOMContentLoaded', () => {
            try {
                const rawDataElement = document.getElementById('raw-json-data');
                if (!rawDataElement || !rawDataElement.textContent.trim()) throw new Error("未能获取到有效的JSON数据。");

                const nameLists = JSON.parse(rawDataElement.textContent);
                const statData = JSON.parse('{{get_message_variable::stat_data}}');
                const allCharsData = statData.characters;

                // 渲染标签的通用函数 (道具/技能)
                const renderTags = (container, items) => {
                    if (!container) return;
                    container.innerHTML = ''; // 清空旧内容

                    if (!items || items.length === 0 || (items.length === 1 && items[0] === '无')) {
                        const span = document.createElement('span');
                        span.style.color = 'var(--text-muted)';
                        span.style.fontSize = '0.9em';
                        span.textContent = '无';
                        container.appendChild(span);
                    } else {
                        items.forEach(itemText => {
                            const li = document.createElement('li');
                            li.className = 'item-tag';
                            li.textContent = itemText;
                            container.appendChild(li);
                        });
                    }
                };

                // 渲染主角模块
                const characterModule = document.querySelector('#character-module-content');
                const userData = allCharsData['<user>'];
                if(userData){
                    const user_hp = userData.attributes.HP;
                    const user_maxHp = userData.attributes.maxHP;
                    const user_mp = userData.attributes.MP;
                    const user_maxMp = userData.attributes.maxMP;

                    characterModule.innerHTML =
                        '<div class="char-header">' +
                        '  <div>' +
                        '    <div class="char-name">' + userData.name + '</div>' +
                        '    <div class="char-meta">' +
                        '      <span>' + (userData.race || '未知') + '</span> | <span>' + (userData.gender || '未知') + '</span> | <span>' + (userData.age !== null ? userData.age + '岁' : '未知') + '</span>' +
                        '    </div>' +
                        '  </div>' +
                        '</div>' +
                        '<div class="progress-bar-container">' +
                        '  <span class="progress-label">HP</span>' +
                        '  <div class="progress-bar-wrapper"><div class="progress-bar hp" style="--val: ' + user_hp + '; --max: ' + user_maxHp + ';"></div></div>' +
                        '  <span class="progress-value">' + user_hp + ' / ' + user_maxHp + '</span>' +
                        '</div>' +
                        '<div class="progress-bar-container">' +
                        '  <span class="progress-label">MP</span>' +
                        '  <div class="progress-bar-wrapper"><div class="progress-bar mp" style="--val: ' + user_mp + '; --max: ' + user_maxMp + ';"></div></div>' +
                        '  <span class="progress-value">' + user_mp + ' / ' + user_maxMp + '</span>' +
                        '</div>' +
                        '<div class="content-section"><h4 class="section-title">道具</h4><ul class="tag-container item-tags"></ul></div>' +
                        '<div class="content-section"><h4 class="section-title">主动技能</h4><ul class="tag-container active-skill-tags"></ul></div>' +
                        '<div class="content-section"><h4 class="section-title">被动技能</h4><ul class="tag-container passive-skill-tags"></ul></div>' +
                        '<div class="content-section"><h4 class="section-title">当前行动</h4><p class="action-status-text">' + (userData.action || '无') + '</p></div>' +
                        '<div class="content-section"><h4 class="section-title">当前状态</h4><p class="action-status-text">' + (userData.status || '无') + '</p></div>';

                    renderTags(document.querySelector('.item-tags'), userData.items);
                    renderTags(document.querySelector('.active-skill-tags'), userData.skills.active);
                    renderTags(document.querySelector('.passive-skill-tags'), userData.skills.passive);
                }

                // 渲染实体列表的通用函数 (队友/NPC)
                const renderEntityList = (contentSelector, nameList, emptyMessage) => {
                    const outerContainer = document.querySelector(contentSelector);
                    if (!outerContainer) return;
                    outerContainer.innerHTML = '';

                    const innerContainer = document.createElement('div');
                    innerContainer.className = 'content-inner-padding';
                    outerContainer.appendChild(innerContainer);

                    if (!nameList || nameList.length === 0) {
                        const p = document.createElement('p');
                        p.style.color = 'var(--text-muted)';
                        p.style.textAlign = 'center';
                        p.textContent = emptyMessage;
                        innerContainer.appendChild(p);
                        return;
                    }

                    const listElement = document.createElement('ul');
                    listElement.className = 'entity-list';
                    innerContainer.appendChild(listElement);

                    nameList.forEach(name => {
                        const charData = allCharsData[name];
                        if (!charData) return;

                        const listItem = document.createElement('li');
                        listItem.className = 'entity-card';
                        listItem.dataset.name = name;

                        const hp = charData.attributes.HP;
                        const maxHp = charData.attributes.maxHP;
                        const mp = charData.attributes.MP;
                        const maxMp = charData.attributes.maxMP;
                        const entityItems = charData.items && charData.items.length > 0 ? charData.items.join(', ') : '无';

                        listItem.innerHTML =
                            '<div class="entity-summary">' +
                            '  <div>' +
                            '    <span class="entity-name">' + charData.name + '</span>' +
                            '    <span class="entity-race">' + charData.race + '</span>' +
                            '  </div>' +
                            '  <span class="entity-status">' + charData.title + '</span>' +
                            '</div>' +
                            '<div class="entity-details">' +
                            '  <div class="detail-grid">' +
                            '    <span class="label">HP:</span> <span class="value">' + hp + ' / ' + maxHp + '</span>' +
                            '    <span class="label">MP:</span> <span class="value">' + mp + ' / ' + maxMp + '</span>' +
                            '    <span class="label">好感度:</span> <span class="value" style="color: var(--favor-color);">' + charData.favorability + '</span>' +
                            '    <span class="label">道具:</span> <span class="value">' + entityItems + '</span>' +
                            '  </div>' +
                            '  <div><strong>主动技能:</strong><ul class="sub-skills-list" data-type="active"></ul></div>' +
                            '  <div style="margin-top: 8px;"><strong>被动技能:</strong><ul class="sub-skills-list" data-type="passive"></ul></div>' +
                            '</div>';

                        listElement.appendChild(listItem);

                        renderTags(listItem.querySelector('.sub-skills-list[data-type="active"]'), charData.skills.active);
                        renderTags(listItem.querySelector('.sub-skills-list[data-type="passive"]'), charData.skills.passive);
                    });
                };

                renderEntityList('.teammate-info', nameLists.teammates, '当前没有队友');
                renderEntityList('.npc-info', nameLists.npcs, '当前没有NPC');

                // 渲染当前事件
                const eventElement = document.getElementById('event-text');
                if (eventElement) {
                    eventElement.textContent = statData.event || '无';
                }

                // 渲染时间和地点
                const timeElement = document.getElementById('time-text');
                if (timeElement) {
                    timeElement.textContent = statData.time || '未知';
                }
                const locationElement = document.getElementById('location-text');
                if (locationElement) {
                    locationElement.textContent = statData.location || '未知';
                }

                // 事件委托处理所有交互
                const panel = document.getElementById('status-panel');
                if (panel) {
                    panel.addEventListener('click', function(event) {
                        const card = event.target.closest('.entity-card');
                        if (card) {
                            card.classList.toggle('expanded');
                            return;
                        }

                        const collapsible = event.target.closest('.collapsible');
                        if (collapsible) {
                            collapsible.classList.toggle('active');
                        }
                    });
                }

            } catch (error) {
                console.error("美化状态栏失败:", error);
                const panel = document.getElementById('status-panel');
                if (panel) { panel.innerHTML = '<div class="module"><div style="color:red;font-weight:bold;">[渲染失败] ' + error.message + '</div></div>'; }
            }
        });
    </script>
</body>

</html>
